// Misma lógica que flujo/clasificar.js
const lead = $json.lead;
const PESO_ORIGEN = { referido: 30, formulario: 20, whatsapp: 20, evento_anterior: 25, anuncio: 10 };
const SENALES = [
  { re: /inscrib|reserv|separar|cupo/i, pts: 30, motivo: 'quiere inscribirse' },
  { re: /precio|cu[aá]nto|costo|pag(o|ar)/i, pts: 20, motivo: 'pregunta por precio o pago' },
  { re: /cu[aá]ndo|fecha|d[oó]nde|lugar|\bhora\b|horario/i, pts: 15, motivo: 'pregunta logística' },
  { re: /grupo|equipo|somos \d+|\d+ personas/i, pts: 15, motivo: 'viene en grupo' },
  { re: /solo informaci|m[aá]s adelante|no s[eé]/i, pts: -15, motivo: 'interés bajo' },
];
const nivel = (p) => (p >= 60 ? 'caliente' : p >= 30 ? 'tibio' : 'frio');

let puntaje = 0;
const motivos = [];
const o = PESO_ORIGEN[lead.origen] ?? 0;
if (o) { puntaje += o; motivos.push(`origen ${lead.origen} (+${o})`); }
for (const s of SENALES) if (s.re.test(lead.mensaje || '')) { puntaje += s.pts; motivos.push(`${s.motivo} (${s.pts > 0 ? '+' : ''}${s.pts})`); }
if (lead.email && lead.telefono) { puntaje += 10; motivos.push('datos completos (+10)'); }
puntaje = Math.max(0, Math.min(100, puntaje));

// Un lead que vuelve a escribir nunca baja de clasificación
if (lead.puntaje != null && lead.puntaje > puntaje) { puntaje = lead.puntaje; motivos.push(`se mantiene puntaje previo (${puntaje})`); }
const clasificacion = nivel(puntaje);

const protegido = ['requiere_humano', 'inscrito', 'confirmado', 'asistio'].includes(lead.etapa);
const accion = protegido ? 'protegido' : !lead.consentimiento ? 'sin_consentimiento' : 'enviar';

const nombre = lead.nombre.split(' ')[0];
const planes = {
  caliente: { plantilla: 'bienvenida_inscripcion', etapa: 'requiere_humano', texto: `Hola ${nombre}, gracias por tu interés. Te escribirá alguien del equipo en breve para ayudarte con tu inscripción.` },
  tibio: { plantilla: 'info_evento', etapa: 'contactado', texto: `Hola ${nombre}, te comparto los detalles del evento (fecha, lugar y precio). ¿Te separo un cupo?` },
  frio: { plantilla: 'nutricion', etapa: 'contactado', texto: `Hola ${nombre}, gracias por escribirnos. Te avisaremos de las próximas fechas.` },
};

return { json: { lead_id: lead.id, etapa_actual: lead.etapa, puntaje, clasificacion, motivos, accion, plan: planes[clasificacion] } };
